INSERT OR IGNORE INTO vehicle_weapons
  (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('cs-mark-vii-slayer-apc', 1, 'C-T60 High-Powered Laser Cannon (1)', '1D6x10 M.D. per blast', 1, '6000 feet (1828 m)', 'Equal to the gunner''s combined hand to hand attacks (usually 3-6)', 'Effectively unlimited', NULL, 'Anti-aircraft and anti-armor, secondary defense. The big gun of the main turret: 45 degree arc up and down, the turret turning 360 degrees. Powered by the vehicle''s nuclear supply.'),
  ('cs-mark-vii-slayer-apc', 2, 'C-PT36 Plasma Mini-Turret (1)', '6D6 M.D. per dual blast', 1, '2000 feet (610 m)', 'Equal to the gunner''s hand to hand attacks (usually 3-6)', 'Effectively unlimited', NULL, 'Anti-armor, secondary anti-personnel. On top of the main turret with its own gunner, independent of the main cannon; the barrel moves in a 30 degree arc.'),
  ('cs-mark-vii-slayer-apc', 3, 'C-MV12 Vertical Mini-Missile Launchers (2)', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10 M.D.)', 1, 'About one mile', 'One at a time or in volleys of two, three or four', '24 total; 12 per launcher', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. Two stacked vertical launchers on the mini-turret.'),
  ('cs-mark-vii-slayer-apc', 4, 'C-M6 Dual Mini-Missile Launchers (2)', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10 M.D.)', 1, 'About one mile', 'One at a time or in volleys of two, three or four', '24 total; 12 per launcher, each fed from internal storage in the main turret', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. Two-shot self-loading launchers on the two sides of the main turret.'),
  ('cs-mark-vii-slayer-apc', 5, 'C-4T Dual Laser Turrets (4)', '4D6 M.D. per single blast, or 1D4x10+8 M.D. per simultaneous dual blast (one melee attack)', 1, '4000 feet (1200 m)', 'Equal to the gunner''s combined hand to hand attacks (usually 4-6)', 'Effectively unlimited', NULL, 'Anti-personnel, secondary defense. Heavy laser pairs on both sides toward the rear, usually gunner-operated against troops and approaching vehicles; full 360 degree rotation and a 90 degree arc.'),
  ('cs-mark-vii-slayer-apc', 6, 'Smoke Dispensers (2)', NULL, 0, NULL, NULL, 'Twenty total, ten each; usually 14 smoke and six tear gas', NULL, 'Rear-mounted; a dense cloud covers an 80 foot (24 m) area behind the APC, or the APC itself when stationary. Can release tear gas instead.'),
  ('cs-mark-ix-epc', 1, 'CR-2T Laser Turret (2)', '4D6 per dual blast (no unit printed)', 1, '4000 feet (1200 m)', 'Equal to the total hand to hand attacks per melee (usually 4 to 6)', 'Effectively unlimited', NULL, 'Anti-personnel, secondary defense. A double-barreled turret on top, 360 degree rotation and a 70 degree arc. Two in the weapon list; the M.D.C. list has one Center Laser Turret.'),
  ('cs-mark-ix-epc', 2, 'CR-10 Forward Mini-Missile Launcher', 'Varies with missile; standard issue fragmentation (5D6 M.D.)', 1, 'One mile (1.6 km)', 'One at a time or in volleys of 2, 3, 5 or 10', 'Twenty (20)', NULL, 'Anti-personnel, secondary defense. A rapid-fire launcher in the front, usually fired by the pilot.'),
  ('ctx-50-line-backer-heavy-assault-tank', 1, 'C-T60 High-Powered Laser Cannons (2)', '1D6x10 M.D. per single blast', 1, '6000 feet (1828 m)', 'Equal to each gunner''s combined hand to hand attacks (usually 3-6 each, 6-12 shots between the two)', 'Effectively unlimited', NULL, 'Anti-aircraft and anti-armor, secondary defense. In a 360 degree ball turret, each worked by its own gunner; they cannot fire in tandem, but both gunners can hit the same target in a coordinated attack.'),
  ('ctx-50-line-backer-heavy-assault-tank', 2, 'C-20R Rail Gun', '1D6x10 M.D. per full 40 round burst; 3D6 M.D. per 10 round burst at the flip of a switch', 1, '4000 feet (1220 m)', 'Equal to the gunner''s combined hand to hand attacks (usually 4-6)', '6000 round drum, 150 bursts per rail gun, 12,000 rounds total. Reloading a drum takes about 15 minutes untrained, five with engineering or field armorer skills', NULL, 'Assault. A general purpose gun for assault, anti-armor and infantry cover fire; the M.D.C. list has two forward rail guns.'),
  ('ctx-50-line-backer-heavy-assault-tank', 3, 'C-20L Laser Turret (1)', '3D6 M.D. per single blast, or 6D6 M.D. per simultaneous double blast (one melee action)', 1, '4000 feet (1200 m)', 'Equal to the gunner''s combined hand to hand attacks (usually 3-6)', 'Effectively unlimited', NULL, 'Anti-armor, secondary anti-personnel. A rear mini-turret with its own gunner, independent of the other weapons; 360 degree rotation and a 45 degree arc.'),
  ('ctx-50-line-backer-heavy-assault-tank', 4, 'CR-8 Medium-Range Missile Launchers (2)', 'Varies with missile type', 1, '40-60 miles (64.3 to 96.9 km) for medium-range missiles', 'One at a time or in volleys of two or four', '16 total; eight per launcher', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. Rear pair firing short or medium-range missiles (medium standard); the missile type line says any medium-range (short in an emergency) "but heavy missiles are standard".'),
  ('ctx-50-line-backer-heavy-assault-tank', 5, 'Concealed Mini-Missile Launchers (2)', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10 M.D.)', 1, 'About one mile', 'One at a time or in volleys of two, three or four', '24 total; 12 per launcher', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. Recessed in the front under the teeth of the Death''s Head; no M.D.C. location is printed for them.'),
  ('ctx-50-line-backer-heavy-assault-tank', 6, 'Smoke Dispensers (2)', NULL, 0, NULL, NULL, 'Twenty total, ten each; usually 14 smoke and six tear gas', NULL, 'Rear-mounted; a dense cloud covers an 80 foot (24 m) area behind the tank, or the tank itself when stationary. Can release tear gas instead.'),
  ('ctx-52-sky-sweeper-anti-aircraft-tank', 1, 'C-T60 High-Powered Laser Cannons (2)', '1D6x10 M.D. per single blast', 1, '6000 feet (1828 m)', 'Equal to each gunner''s combined hand to hand attacks (usually 3-6 each, 6-12 shots between the two)', 'Effectively unlimited', NULL, 'Anti-aircraft and anti-armor, secondary defense. A forward-facing swivel housing with a 180 degree arc, so the whole turret turns to aim; each cannon has its own gunner. They cannot fire in tandem but can hit the same target in a coordinated attack.'),
  ('ctx-52-sky-sweeper-anti-aircraft-tank', 2, 'C-44R Rail Gun Turrets (2)', '2D6x10 M.D. per full 80 round burst; 1D6x10 M.D. per 40 round burst at the flip of a switch', 1, '4000 feet (1220 m)', 'Equal to the gunner''s combined hand to hand attacks (usually 4-6)', '12,000 round drum, 150 full bursts per rail gun, 24,000 rounds total. Reloading a drum takes about 20 minutes untrained, five with engineering or field armorer skills', NULL, 'Anti-aircraft, secondary anti-personnel and defense. High-powered double-barreled turrets in the front, one worked by the pilot and one by the co-pilot; general purpose weapons also suited to assault, anti-armor and infantry cover.'),
  ('ctx-52-sky-sweeper-anti-aircraft-tank', 3, 'C-20L Double-Barrel Laser Turret (1)', '3D6 M.D. per single blast, or 6D6 M.D. per simultaneous double blast (one melee action)', 1, '4000 feet (1200 m)', 'Equal to the gunner''s combined hand to hand attacks (usually 3-6)', 'Effectively unlimited', NULL, 'Anti-armor, secondary anti-personnel. A rear mini-turret with its own gunner, independent of the other weapons; 360 degree rotation and a 45 degree arc.'),
  ('ctx-52-sky-sweeper-anti-aircraft-tank', 4, 'CR-8 Medium-Range Missile Launchers (2)', 'Varies with missile type', 1, '40-60 miles (64.3 to 96.9 km) for medium-range missiles', 'One at a time or in volleys of two or four', '10 total; five per launcher', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. Short or medium-range missiles (medium standard), usually fired by one of the cannon gunners; the missile type line says "heavy missiles are standard". This entry puts them in the rear; the M.D.C. list on the sides.'),
  ('ctx-52-sky-sweeper-anti-aircraft-tank', 5, 'Concealed Mini-Missile Launch Tubes (4)', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10 M.D.)', 1, 'About one mile', 'One at a time or in volleys of two, three or four', 'Eight total; two per tube', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. Under the back hood of the turret, worked by one of the gunners; the text calls them "a pair" though four are numbered.'),
  ('ctx-52-sky-sweeper-anti-aircraft-tank', 6, 'Smoke Dispensers (2)', NULL, 0, NULL, NULL, 'Ten total, five each; usually eight smoke and two tear gas', NULL, 'Rear-mounted; a dense cloud covers an 80 foot (24 m) area behind the tank, or the tank itself when stationary. Can release tear gas instead.'),
  ('ctx-54-fire-storm-mobile-fortress', 1, 'C-2000 Super Rail Cannons (2)', '1D4x100 M.D. per single blast or 2D8x100 M.D. per double blast; both at once only against a target wider than 60 feet (18.3 m)', 1, 'Two miles (3.2 km)', 'Eight blasts per melee round, four per cannon; each worked by a gunner and a communications officer', '2000 blasts; 1000 per cannon', NULL, 'Anti-armor and anti-aircraft, secondary bombardment of enemy installations. Experimental: two long barrels along the neck of the Command Deck, firing forward with 25 degrees of elevation. Both are often fired at targets over a mile (1.6 km) away so one hits (-1 to strike).'),
  ('ctx-54-fire-storm-mobile-fortress', 2, 'C-300DH Rail Gun Turrets (2)', '3D4x10 M.D. per 100 round burst', 1, 'Two miles (3.2 km)', 'Equal to the gunner''s combined hand to hand attacks (usually 4-6)', '100,000 rounds per gun, 1000 bursts; reloading needs special equipment and about an hour. Each turret also has ten side ports with 20 mini-missiles (standard range and damage by type), fired singly or in volleys of two, four, six or ten', NULL, 'Anti-aircraft and anti-power armor, secondary anti-armor (tanks, robots, dragons). Large dual cannon turrets on top of the Command Center either side of the Command Deck, on their own nuclear supplies; 360 degree rotation and an 80 degree sweep; two gunners and a communications officer each.'),
  ('ctx-54-fire-storm-mobile-fortress', 3, 'C-60T Command Deck Laser Turret (1)', '2D4x10 M.D. per simultaneous double blast', 1, '6000 feet (1828 m)', 'Eight blasts per melee round; worked by two gunners and a communications officer', 'Effectively unlimited', NULL, 'Anti-armor, secondary anti-personnel and defense. A heavy double-barreled laser cannon in the chin of the Command Deck''s Death''s Head; 180 degree rotation and a 90 degree arc.'),
  ('ctx-54-fire-storm-mobile-fortress', 4, 'Long-Range Missile Battery', 'Varies with missile; standard issue high explosive and plasma (2D6x10 M.D.) and/or multi-warhead smart bombs (2D4x10 M.D., +5 to strike)', 1, 'Over 500 miles (800 km)', 'One at a time or in volleys of two or four', '32 total', NULL, 'Anti-armor and anti-aircraft, secondary bombardment of enemy installations. The top four of the eight sliding hatches on each side of the Command Deck (eight launchers), each able to fire two at a time.'),
  ('ctx-54-fire-storm-mobile-fortress', 5, 'Medium-Range Missile Battery', 'Varies with missile; standard issue high explosive and plasma (2D6x10 M.D.) and/or multi-warhead smart bombs (2D4x10 M.D., +5 to strike)', 1, 'Over 40 miles (64 km)', 'One at a time or in volleys of two or four', '64 total', NULL, 'Anti-armor and anti-aircraft, secondary bombardment of enemy installations. The bottom four hatches on each side (eight launchers); short-range missiles can be fired if medium-range are not available.'),
  ('ctx-54-fire-storm-mobile-fortress', 6, 'C-2T Dual Laser Turrets (24)', '4D6 M.D. per dual blast', 1, '4000 feet (1200 m)', 'Up to six times per melee with a gunner, four times automated', 'Effectively unlimited', NULL, 'Anti-personnel, secondary defense. A pair at or over every bay door, each pair assigned a gunner; short of manpower, a small targeting computer and sensors fire them at identified enemies. 360 degree rotation and a 90 degree arc.'),
  ('afc-151-death-bringer-apc', 1, 'CPC-100 High-Powered Cannon Turret (1)', '1D6x10 M.D. per round', 1, '8000 feet (2438.4 m)', 'Equal to the gunner''s hand to hand attacks per melee +1 (usually 3 to 6)', '100 rounds', '+1 to strike', 'Assault/anti-armor/anti-monster, secondary defense. Fires plasma rocket shells equal to a mini-missile but unguided. The turret, with its sensor disk and antenna, turns 360 degrees; the cannon rises through a 45 degree arc. Usually an independent gunner.'),
  ('afc-151-death-bringer-apc', 2, 'Laser Turrets (6)', '3D6 M.D. per single blast or 6D6 per simultaneous double blast', 1, '4000 feet (1200 m)', 'Equal to the pilot''s or gunner''s hand to hand attacks per melee (typically 3-6)', 'Effectively unlimited', NULL, 'Assault, secondary anti-missile. A pair front, a pair back and one above each side Death''s Head bay door; 360 degree rotation and a 180 degree arc. Not keyed to fire in tandem: the pilot and/or co-pilot work the forward pair, one gunner the rear pair and one gunner each side turret.'),
  ('afc-060-sky-lifter-apc', 1, 'CPC-200 Double-Barrel High-Powered Cannon Turret (1)', '1D6x10 M.D. per single round or 2D6x10 per double round', 1, '8000 feet (2438.4 m)', 'Equal to the gunner''s hand to hand attacks per melee +1 (usually 3 to 6)', '300 rounds', '+1 to strike', 'Assault/anti-armor/anti-monster, secondary defense. A concealed cannon firing plasma rocket shells; the weapon rises to fire while its fixed front section is the sensor unit. Raised, it turns 360 degrees and tilts 45 degrees. Usually a gunner. The prose calls it a concealed rail gun.'),
  ('afc-060-sky-lifter-apc', 2, 'Concealed Mini-Missile Launchers (4)', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10 M.D.)', 1, 'About one mile', 'One at a time or in volleys of two, four or eight', '400 total; 100 in each triangular launch unit', NULL, 'Anti-aircraft and anti-armor, secondary anti-personnel. The triangular markings toward the front; each pair is worked by a gunner. The prose calls them medium-range missile launchers.'),
  ('afc-101-cs-command-car', 1, 'C-30R Light Rail Gun', '6D6 M.D. per 30 round burst; one round 1D4 M.D.', 1, 'Two miles (3.2 km)', 'Equal to the combined hand to hand attacks (usually 4-6)', '2400 rounds, 80 bursts', NULL, 'Anti-personnel, secondary defense. On a retractable mounting in the back with a tail gunner''s seat; the gun weighs 90 lbs (40.8 kg), its ammo compartment inside the car.'),
