  FROM vehicle_weapons WHERE vehicle_slug IN ('cs-mark-vii-slayer-apc', 'cs-mark-ix-epc', 'ctx-50-line-backer-heavy-assault-tank', 'ctx-52-sky-sweeper-anti-aircraft-tank', 'ctx-54-fire-storm-mobile-fortress', 'afc-151-death-bringer-apc', 'afc-060-sky-lifter-apc', 'afc-101-cs-command-car', 'afc-103-scarab-officers-car', 'afc-105-skull-patrol-car', 'afc-111-scout-rocket-cycle', 'afc-115-warbird-rocket-cycle', 'afc-033-wind-jammer-sky-cycle', 'ch-10-black-lightning-combat-helicopter', 'ch-12-demon-locust-combat-helicopter', 'sf-7-talon-stealth-vtol-jet-fighter');

SELECT 'main bodies: 500+220+790+400+5000+900+2300+180+240+200+150+220+220+200+250+350' AS assertion, sum(mdc_main_body) AS got, 12120 AS want
  FROM vehicles WHERE slug IN ('cs-mark-vii-slayer-apc', 'cs-mark-ix-epc', 'ctx-50-line-backer-heavy-assault-tank', 'ctx-52-sky-sweeper-anti-aircraft-tank', 'ctx-54-fire-storm-mobile-fortress', 'afc-151-death-bringer-apc', 'afc-060-sky-lifter-apc', 'afc-101-cs-command-car', 'afc-103-scarab-officers-car', 'afc-105-skull-patrol-car', 'afc-111-scout-rocket-cycle', 'afc-115-warbird-rocket-cycle', 'afc-033-wind-jammer-sky-cycle', 'ch-10-black-lightning-combat-helicopter', 'ch-12-demon-locust-combat-helicopter', 'sf-7-talon-stealth-vtol-jet-fighter');

SELECT 'printed prices, low ends, in credits (the four estimates are NULL)' AS assertion, sum(cost) AS got, 100275000 AS want
  FROM vehicles WHERE slug IN ('cs-mark-vii-slayer-apc', 'cs-mark-ix-epc', 'ctx-50-line-backer-heavy-assault-tank', 'ctx-52-sky-sweeper-anti-aircraft-tank', 'ctx-54-fire-storm-mobile-fortress', 'afc-151-death-bringer-apc', 'afc-060-sky-lifter-apc', 'afc-101-cs-command-car', 'afc-103-scarab-officers-car', 'afc-105-skull-patrol-car', 'afc-111-scout-rocket-cycle', 'afc-115-warbird-rocket-cycle', 'afc-033-wind-jammer-sky-cycle', 'ch-10-black-lightning-combat-helicopter', 'ch-12-demon-locust-combat-helicopter', 'sf-7-talon-stealth-vtol-jet-fighter');

SELECT 'every vehicle has one main body location matching mdc_main_body' AS assertion, count(*) AS got, 16 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location IN ('Main Body', 'Main Body: Command Center (1)')
  WHERE v.slug IN ('cs-mark-vii-slayer-apc', 'cs-mark-ix-epc', 'ctx-50-line-backer-heavy-assault-tank', 'ctx-52-sky-sweeper-anti-aircraft-tank', 'ctx-54-fire-storm-mobile-fortress', 'afc-151-death-bringer-apc', 'afc-060-sky-lifter-apc', 'afc-101-cs-command-car', 'afc-103-scarab-officers-car', 'afc-105-skull-patrol-car', 'afc-111-scout-rocket-cycle', 'afc-115-warbird-rocket-cycle', 'afc-033-wind-jammer-sky-cycle', 'ch-10-black-lightning-combat-helicopter', 'ch-12-demon-locust-combat-helicopter', 'sf-7-talon-stealth-vtol-jet-fighter')
    AND l.mdc = v.mdc_main_body;

